AND (1 = 0 OR S.ORG_MSTR_CODE IS NULL OR S.ORG_CODE IS NULL
OR (S.ORG_MSTR_CODE = #{district.regionCode} AND S.ORG_CODE = #{district.districtCode})
)

WHERE S.LIB_ID = #{libId}
  AND S.DEL_IND = #{f.deleted}


  AND S.ORG_MSTR_CODE = #{f.regionCode} AND S.ORG_CODE = #{f.districtCode}

 AND BINARY S.CALL_STATUS = BINARY #{f.callStatus} 
 AND BINARY S.CALL_RESULT = BINARY #{f.callResult} 
 AND S.FOUND_DATE >= #{f.foundFrom} 
 AND S.FOUND_DATE <= #{f.foundTo} 
 AND S.SYS_RUSR_DTTM >= #{f.createdFrom} 
 AND S.ASSIGNED_USER_ID = #{f.assignedUserId} 

     AND (S.ASSIGNED_USER_ID IS NOT NULL OR S.ASSIGNED_USER_NAME <> '') 
     AND S.ASSIGNED_USER_ID IS NULL AND S.ASSIGNED_USER_NAME = '' 


     AND S.MANPIK_CONFIRMED_AT IS NOT NULL 
     AND S.MANPIK_CONFIRMED_AT IS NULL 


    AND  NOT  EXISTS (
        SELECT 1 FROM CALLSHEETROUND R
         WHERE R.LIB_ID = S.LIB_ID AND R.SHEET_ID = S.SHEET_ID AND R.ROUND_CODE = #{f.roundCode}
    )

 AND S.PHONE_LAST4 = #{f.phoneLast4} 

    AND (
        S.TARGET_NAME LIKE #{f.qLike} ESCAPE '!'
        OR S.INTRO_NAME LIKE #{f.qLike} ESCAPE '!'
        OR S.RESIDENCE LIKE #{f.qLike} ESCAPE '!'
        OR S.PREFERRED_PLACE LIKE #{f.qLike} ESCAPE '!'
        OR S.NOTES LIKE #{f.qLike} ESCAPE '!'
        OR S.CONSULT_TOPIC LIKE #{f.qLike} ESCAPE '!'
        OR S.CALL_STATUS LIKE #{f.qLike} ESCAPE '!'
        OR S.CALL_RESULT LIKE #{f.qLike} ESCAPE '!'
        OR S.ASSIGNED_USER_NAME LIKE #{f.qLike} ESCAPE '!'
        OR S.MANPIK_INFO LIKE #{f.qLike} ESCAPE '!'
        OR EXISTS (
            SELECT 1 FROM CALLSHEETROUND R WHERE R.LIB_ID = S.LIB_ID AND R.SHEET_ID = S.SHEET_ID
               AND R.CALLER_NAME LIKE #{f.qLike} ESCAPE '!'
        )
         OR S.PHONE_LAST4 = #{f.qLast4} 
    )

mapper.select:
SELECT R.SHEET_ID AS sheetId, R.ROUND_CODE AS code, R.ROUND_LABEL AS label,
       R.CALLER_USER_ID AS callerUserId, R.CALLER_NAME AS callerName
  FROM CALLSHEETROUND R WHERE R.LIB_ID = #{libId}


        AND R.SHEET_ID IN
        #{id}

    AND 1 = 0

SELECT DISTINCT S.CALL_STATUS COLLATE utf8mb4_bin AS statusValue FROM CALLSHEET S
 WHERE S.LIB_ID = #{libId} AND S.DEL_IND = 'N' AND S.CALL_STATUS <> ''

 ORDER BY statusValue LIMIT #{limit}

SELECT DISTINCT S.CALL_RESULT COLLATE utf8mb4_bin AS resultValue FROM CALLSHEET S
 WHERE S.LIB_ID = #{libId} AND S.DEL_IND = 'N' AND S.CALL_RESULT <> ''

 ORDER BY resultValue LIMIT #{limit}

SELECT S.TGT_ID AS id, S.TGT_NAME_HAN AS name, S.TGT_CODE AS code, S.ORG_MSTR_CODE AS regionCode, S.ORG_CODE AS districtCode FROM TGMSTR S WHERE S.LIB_ID = #{libId} AND S.DEL_IND = 'N'
AND (S.TGT_NAME_HAN LIKE #{qLike} ESCAPE '!' OR S.TGT_CODE LIKE #{qLike} ESCAPE '!')
ORDER BY S.TGT_NAME_HAN, S.TGT_ID LIMIT #{limit}

SELECT S.EMPL_ID AS id, S.EMPL_NAME_HAN AS name, S.EMPL_CODE AS code, S.ORG_MSTR_CODE AS regionCode, S.ORG_CODE AS districtCode FROM PSMSTR S WHERE S.USE_IND = 'Y'
AND (S.EMPL_NAME_HAN LIKE #{qLike} ESCAPE '!' OR S.EMPL_CODE LIKE #{qLike} ESCAPE '!')
ORDER BY S.EMPL_NAME_HAN, S.EMPL_ID LIMIT #{limit}

mapper.update:
UPDATE CALLSHEET S
TGT_ID = #{targetId}, CALL_STATUS = #{callStatus}, FOUND_DATE = #{foundDate}, CALL_RESULT = #{callResult}, TARGET_NAME = #{targetName}, INTRO_EMPL_ID = #{introducerId}, INTRO_NAME = #{introducerName}, ORG_MSTR_CODE = #{regionCode}, ORG_CODE = #{districtCode}, SEX_CODE = #{sexCode}, AGE_TEXT = #{ageText}, RESIDENCE = #{residence}, PREFERRED_PLACE = #{preferredPlace}, NOTES = #{notes}, CONSULT_TOPIC = #{consultTopic}, MANPIK_CONFIRMED_AT = #{manpikConfirmedAt}, MANPIK_INFO = #{manpikInfo}, ASSIGNED_USER_ID = #{assignedUserId}, ASSIGNED_USER_NAME = #{assignedUserName},
PHONE_ENC = #{phoneEnc}, PHONE_LAST4 = #{phoneLast4}, PHONE_KEY_VER = #{phoneKeyVer},
SOURCE_ENC = #{sourceEnc}, ROW_VERSION = ROW_VERSION + 1, SYS_MUSR_ID = #{sysUserId}, SYS_MUSR_IP = #{sysIp}, SYS_MUSR_DTTM = #{sysAt}
WHERE S.LIB_ID = #{libId} AND S.SHEET_ID = #{id} AND S.DEL_IND = 'N' AND S.ROW_VERSION = #{expectedVersion}

UPDATE CALLSHEET S
   SET DEL_IND = #{toInd}, ROW_VERSION = ROW_VERSION + 1,
       SYS_MUSR_ID = #{sysUserId}, SYS_MUSR_IP = #{sysIp}, SYS_MUSR_DTTM = #{sysAt}
 WHERE S.LIB_ID = #{libId} AND S.SHEET_ID = #{id} AND S.DEL_IND = #{fromInd}
   AND S.ROW_VERSION = #{expectedVersion}

