INSERT INTO CALLSHEETROUND (
    LIB_ID, SHEET_ID, ROUND_CODE, ROUND_LABEL, CALLER_USER_ID, CALLER_NAME,
    SYS_RUSR_ID, SYS_RUSR_IP, SYS_RUSR_DTTM, SYS_MUSR_ID, SYS_MUSR_IP, SYS_MUSR_DTTM
) VALUES (
    #{libId}, #{sheetId}, #{code}, #{label}, #{callerUserId}, #{callerName},
    #{sysUserId}, #{sysIp}, #{sysAt}, #{sysUserId}, #{sysIp}, #{sysAt}
)
ON DUPLICATE KEY UPDATE ROUND_LABEL = VALUES(ROUND_LABEL), CALLER_USER_ID = VALUES(CALLER_USER_ID),
    CALLER_NAME = VALUES(CALLER_NAME), SYS_MUSR_ID = VALUES(SYS_MUSR_ID),
    SYS_MUSR_IP = VALUES(SYS_MUSR_IP), SYS_MUSR_DTTM = VALUES(SYS_MUSR_DTTM)

