SELECT C.SEQ_NO AS seq, C.ENTRY_HASH AS hash
  FROM CHGLOG C WHERE C.LIB_ID = #{libId}
 ORDER BY C.SEQ_NO DESC, C.CHG_ID DESC LIMIT 1 FOR UPDATE
